import json
import re
KB = {
    "KB-01": "Documents are organized in folders by process.",
    "KB-02": "Customer requests need an assigned status."
}
def tokens(text):
    return set(re.findall(r"\w+", text.casefold()))
def retrieve(query):
    query_words = tokens(query)
    hits = []
    for source_id, text in KB.items():
        score = len(query_words & tokens(text))
        if score:
            hits.append({"source_id": source_id, "excerpt": text,
                         "score": score})
    return sorted(hits, key=lambda hit: (-hit["score"], hit["source_id"]))

assert retrieve("documents")[0]["source_id"] == "KB-01"
assert retrieve("volcano astronomy") == []
print(json.dumps(retrieve("customer requests status"), indent=2))

import json
import re

PATTERN = re.compile(r"Package: (\d+) items; category: ([a-z]+)")
def extract(text):
    match = PATTERN.fullmatch(text.strip())
    if not match:
        return {"quantity": None, "category": None,
                "valid": False, "issues": ["format"]}
    quantity, category = int(match[1]), match[2]
    issues = []
    if not 1 <= quantity <= 10000:
        issues.append("quantity_range")
    if category not in {"office", "support", "data"}:
        issues.append("category_enum")
    return {"quantity": quantity, "category": category,
            "valid": not issues, "issues": issues}

assert extract("Package: 12 items; category: office")["valid"]
assert extract("Package: 0 items; category: office")["issues"] == ["quantity_range"]
assert extract("nothing")["quantity"] is None
print(json.dumps(extract("Package: 12 items; category: unknown"), indent=2))

import ast
import json

def review(source):
    try:
        tree = ast.parse(source)
    except SyntaxError as error:
        return {"status": "parse_error", "line": error.lineno}
    findings = []
    for node in ast.walk(tree):
        if (isinstance(node, ast.Call) and
            isinstance(node.func, ast.Name) and node.func.id == "eval"):
            findings.append({"line": node.lineno, "rule": "dynamic_eval",
                             "severity": "high"})
    return {"status": "checked",
            "findings": sorted(findings, key=lambda item: item["line"])}

assert review('text = "eval(x)"')["findings"] == []
assert review("# eval(x)\nx = 1")["findings"] == []
assert review("x = (")["status"] == "parse_error"
