import json

def evaluate(expected, predicted, labels):
    if not expected or len(expected) != len(predicted):
        raise ValueError("Expected equal nonempty arrays")
    if not labels or len(set(labels)) != len(labels):
        raise ValueError("Expected distinct labels")
    if not set(expected + predicted) <= set(labels):
        raise ValueError("Unknown label")
    matrix = {a: {b: 0 for b in labels} for a in labels}
    for actual, predicted_label in zip(expected, predicted):
        matrix[actual][predicted_label] += 1
    per_class = {}
    for label in labels:
        tp = sum(a == label and b == label for a, b in zip(expected, predicted))
        fp = sum(a != label and b == label for a, b in zip(expected, predicted))
        fn = sum(a == label and b != label for a, b in zip(expected, predicted))
        denominator = 2 * tp + fp + fn
        per_class[label] = {"tp": tp, "fp": fp, "fn": fn,
                            "f1": 2 * tp / denominator if denominator else 0.0}
    correct = sum(a == b for a, b in zip(expected, predicted))
    return {"correct": correct, "total": len(expected),
            "accuracy": correct / len(expected), "confusion_matrix": matrix,
            "per_class": per_class,
            "macro_f1": sum(v["f1"] for v in per_class.values()) / len(labels)}

labels = ["billing", "support", "hr", "other"]
report = evaluate(labels, ["billing", "support", "other", "other"], labels)
assert report["accuracy"] == 0.75
assert report["per_class"]["hr"]["fn"] == 1
assert report["per_class"]["other"]["fp"] == 1
print(json.dumps(report, indent=2))

import json

ALLOWED = {"billing", "support", "hr", "other"}
exported_versions = set()
def prepare_export(proposal, approved_version):
    if proposal["category"] not in ALLOWED:
        return {"state": "invalid", "external_action": False}
    if approved_version != proposal["version"]:
        return {"state": "awaiting_approval", "external_action": False}
    key = (proposal["id"], proposal["version"])
    if key in exported_versions:
        return {"state": "already_prepared", "external_action": False}
    exported_versions.add(key)
    return {"state": "ready_for_manual_export", "external_action": False,
            "proposal_id": proposal["id"], "version": proposal["version"]}

proposal = {"id": "P-01", "version": 2, "category": "billing"}
assert prepare_export(proposal, 1)["state"] == "awaiting_approval"
ready = prepare_export(proposal, 2)
assert ready["state"] == "ready_for_manual_export"
assert prepare_export(proposal, 2)["state"] == "already_prepared"
assert ready["external_action"] is False
